package regression

import("context";"database/sql";"fmt";"path/filepath";"strata-weave/internal/model";"strata-weave/internal/service";"strata-weave/internal/store";"sync";"testing";"time")
func setupBug005(t *testing.T)(*service.Service,*sql.DB){t.Helper();db,e:=store.Open(filepath.Join(t.TempDir(),"field.db"));if e!=nil{t.Fatal(e)};t.Cleanup(func(){_=db.Close()});app:=service.New(db);if _,e=app.CreateTrench(context.Background(),model.Trench{ID:"t1",Code:"T-1",Site:"Ridge"});e!=nil{t.Fatal(e)};if _,e=app.CreateUnit(context.Background(),model.Unit{ID:"u1",TrenchID:"t1",Code:"U-1",Phase:1});e!=nil{t.Fatal(e)};return app,db}
func TestBug005_BatchAndSingleTelemetryShareLedger(t *testing.T){app,_:=setupBug005(t);obs:=func(id string)model.Observation{return model.Observation{ID:id,UnitID:"u1",Instrument:"total-station",Metric:"elevation",Value:10,At:time.Now(),Quality:"verified"}};var wg sync.WaitGroup;wg.Add(2);go func(){defer wg.Done();_,_=app.IngestBatch(context.Background(),[]model.Observation{obs("batch-1"),obs("batch-2")})}();go func(){defer wg.Done();for n:=0;n<50;n++{_=app.IngestObservation(context.Background(),obs(fmt.Sprintf("single-%d",n)))}}();wg.Wait()}
